:root {
  --color-primary: #c41e3a;
  --color-primary-dark: #8b1528;
  --color-primary-light: #f5e6e8;
  --color-accent-on-dark: #ffb3ba;
  --color-text: #1a1a1a;
  --color-text-light: #555;
  --color-bg: #ffffff;
  --color-border: #e0e0e0;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --font-serif: Georgia, "Times New Roman", serif;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-mono: "Courier New", monospace;
  --transition: all 0.3s ease;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  padding: 0;
  font-family: var(--font-sans);
  color: var(--color-text);
  background-color: var(--color-bg);
  line-height: 1.6;
  font-size: clamp(1rem, 2vw, 1.125rem);
}

.container {
  max-width: 900px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
  width: 100%;
}

/* Typography */

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  color: var(--color-text);
  margin-top: var(--spacing-lg);
  margin-bottom: var(--spacing-md);
  line-height: 1.2;
}

h1 {
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 700;
}

h2 {
  font-size: clamp(1.5rem, 4vw, 2.25rem);
  font-weight: 700;
}

h3 {
  font-size: clamp(1.25rem, 3vw, 1.75rem);
  font-weight: 600;
}

p {
  margin: 0 0 var(--spacing-md) 0;
}

a {
  color: var(--color-primary-dark);
  text-decoration: none;
  transition: var(--transition);
  position: relative;
}

a:hover {
  color: var(--color-primary);
  text-decoration: underline;
}

a:focus {
  outline: 3px solid var(--color-primary);
  outline-offset: 2px;
  border-radius: 2px;
}

/* Header and Navigation */

.site-header {
  background-color: var(--color-bg);
  border-bottom: 2px solid var(--color-border);
  padding: var(--spacing-md) 0;
  position: sticky;
  top: 0;
  z-index: 100;
}

.site-header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--spacing-md);
}

.logo {
  font-family: var(--font-serif);
  font-size: clamp(1.2rem, 3vw, 1.5rem);
  font-weight: 700;
  color: var(--color-primary-dark);
  text-decoration: none;
  letter-spacing: 0.05em;
  white-space: nowrap;
}

.logo:focus {
  outline-offset: 4px;
}

.nav-secondary {
  display: flex;
  gap: var(--spacing-md);
  flex-wrap: wrap;
  justify-content: flex-end;
  align-items: center;
}

.nav-secondary a {
  font-weight: 500;
  font-size: 0.95rem;
  color: var(--color-primary-dark);
  padding: var(--spacing-xs) var(--spacing-sm);
  border-radius: 4px;
  transition: var(--transition);
}

.nav-secondary a:hover {
  background-color: var(--color-primary-light);
  text-decoration: none;
}

.nav-secondary a:focus {
  outline: 3px solid var(--color-primary);
}

/* Footer */

.site-footer {
  background-color: var(--color-primary-dark);
  color: white;
  margin-top: var(--spacing-xl);
  padding: var(--spacing-xl) 0;
}

.site-footer a {
  color: var(--color-accent-on-dark);
}

.site-footer a:hover {
  color: white;
}

.site-footer p {
  margin-bottom: var(--spacing-md);
  font-size: 0.95rem;
}

/* Buttons */

button, .btn, input[type="submit"], input[type="reset"] {
  display: inline-block;
  padding: var(--spacing-sm) var(--spacing-md);
  min-height: 44px;
  min-width: 44px;
  background-color: var(--color-primary-dark);
  color: white;
  border: none;
  border-radius: 6px;
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition);
  text-decoration: none;
  text-align: center;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-xs);
}

button:hover, .btn:hover, input[type="submit"]:hover, input[type="reset"]:hover {
  background-color: var(--color-primary);
}

button:focus, .btn:focus, input[type="submit"]:focus, input[type="reset"]:focus {
  outline: 3px solid var(--color-primary);
  outline-offset: 2px;
}

button:disabled {
  background-color: #999;
  cursor: not-allowed;
  opacity: 0.7;
}

/* Forms */

form {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}

label {
  display: block;
  font-weight: 600;
  margin-bottom: var(--spacing-xs);
  color: var(--color-text);
}

input[type="text"],
input[type="email"],
input[type="tel"],
input[type="number"],
input[type="date"],
input[type="time"],
select,
textarea {
  font-family: var(--font-sans);
  font-size: 1rem;
  padding: var(--spacing-sm);
  border: 2px solid var(--color-border);
  border-radius: 6px;
  transition: var(--transition);
  width: 100%;
  min-height: 44px;
  color: var(--color-text);
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus,
input[type="number"]:focus,
input[type="date"]:focus,
input[type="time"]:focus,
select:focus,
textarea:focus {
  border-color: var(--color-primary-dark);
  outline: none;
  box-shadow: 0 0 0 3px rgba(139, 21, 40, 0.15);
}

textarea {
  resize: vertical;
  min-height: 120px;
  padding: var(--spacing-sm);
}

input[type="checkbox"],
input[type="radio"] {
  margin-right: var(--spacing-xs);
  cursor: pointer;
  min-width: 20px;
  min-height: 20px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-xs);
}

.form-group.checkbox-group,
.form-group.radio-group {
  gap: var(--spacing-sm);
}

.form-group.checkbox-group label,
.form-group.radio-group label {
  display: flex;
  align-items: center;
  margin-bottom: 0;
  font-weight: 400;
}

/* Card component */

.card {
  background-color: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-lg);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  transition: var(--transition);
}

.card:hover {
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12);
}

/* Grid helper */

.grid {
  display: grid;
  gap: var(--spacing-lg);
}

.grid-cols-2 {
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
}

/* Hero section */

.hero {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: white;
  padding: clamp(3rem, 8vw, 5rem) 0;
  text-align: center;
  margin-bottom: var(--spacing-xl);
}

.hero h1 {
  color: white;
  margin-bottom: var(--spacing-md);
}

.hero p {
  font-size: clamp(1.1rem, 2vw, 1.25rem);
  margin-bottom: var(--spacing-lg);
  color: var(--color-accent-on-dark);
}

/* Section */

section {
  margin-bottom: var(--spacing-xl);
  scroll-margin-top: 80px;
}

.section-header {
  margin-bottom: var(--spacing-lg);
}

/* Responsive Design */

@media (max-width: 600px) {
  :root {
    --spacing-lg: 1.5rem;
    --spacing-xl: 2rem;
  }

  .site-header .container {
    flex-direction: column;
    align-items: flex-start;
  }

  .nav-secondary {
    width: 100%;
    justify-content: flex-start;
    gap: var(--spacing-sm);
  }

  .nav-secondary a {
    padding: var(--spacing-xs) var(--spacing-sm);
    font-size: 0.9rem;
  }

  h1 {
    font-size: clamp(1.5rem, 5vw, 2rem);
  }

  h2 {
    font-size: clamp(1.25rem, 4vw, 1.5rem);
  }

  .hero {
    padding: 2rem var(--spacing-md);
  }

  .grid {
    gap: var(--spacing-md);
  }

  .grid-cols-2 {
    grid-template-columns: 1fr;
  }

  button, .btn, input[type="submit"], input[type="reset"] {
    width: 100%;
  }

  input[type="text"],
  input[type="email"],
  input[type="tel"],
  input[type="number"],
  input[type="date"],
  input[type="time"],
  select,
  textarea {
    font-size: 16px;
  }
}

@media (min-width: 601px) {
  .site-header .container {
    flex-direction: row;
  }

  .nav-secondary {
    gap: var(--spacing-lg);
  }

  .grid-cols-2 {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

