.event-details-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: var(--spacing-lg);
  margin-top: var(--spacing-lg);
}

.event-detail-card {
  background-color: var(--color-primary-light);
  border-left: 4px solid var(--color-primary-dark);
  padding: var(--spacing-md);
  border-radius: 4px;
}

.event-detail-card h3 {
  color: var(--color-primary-dark);
  margin-top: 0;
  margin-bottom: var(--spacing-sm);
  font-size: 1.1rem;
}

.event-detail-card p {
  margin: 0;
  color: var(--color-text);
  line-height: 1.5;
}

.about-content {
  max-width: 800px;
}

.about-content h3 {
  margin-top: var(--spacing-lg);
  margin-bottom: var(--spacing-md);
  color: var(--color-primary-dark);
}

.impact-list {
  list-style: none;
  padding: 0;
  margin: var(--spacing-md) 0;
}

.impact-list li {
  padding: var(--spacing-sm) 0 var(--spacing-sm) var(--spacing-lg);
  border-left: 3px solid var(--color-primary-dark);
  padding-left: var(--spacing-md);
  margin-bottom: var(--spacing-sm);
  color: var(--color-text);
}

.rsvp-section {
  background-color: var(--color-primary-light);
  padding: var(--spacing-lg) 0;
  margin-left: -999px;
  margin-right: -999px;
  padding-left: calc(999px + var(--spacing-md));
  padding-right: calc(999px + var(--spacing-md));
}

.rsvp-form {
  max-width: 600px;
  background-color: white;
  padding: var(--spacing-lg);
  border-radius: 8px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  margin-top: var(--spacing-lg);
}

.rsvp-form .form-group label {
  color: var(--color-text);
}

.rsvp-form input[type="text"],
.rsvp-form input[type="email"],
.rsvp-form input[type="tel"],
.rsvp-form input[type="number"],
.rsvp-form textarea {
  border-color: var(--color-border);
}

.rsvp-form button {
  margin-top: var(--spacing-md);
  width: 100%;
}

@media (max-width: 600px) {
  .event-details-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .rsvp-section {
    margin-left: calc(-1 * (100vw - 100%) / 2);
    margin-right: calc(-1 * (100vw - 100%) / 2);
    padding-left: calc((100vw - 100%) / 2 + var(--spacing-md));
    padding-right: calc((100vw - 100%) / 2 + var(--spacing-md));
  }

  .rsvp-form {
    padding: var(--spacing-md);
  }

  .rsvp-form button {
    width: 100%;
  }
}

@media (min-width: 601px) {
  .event-details-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .rsvp-form {
    margin: var(--spacing-lg) auto 0;
  }
}

